from django.db import migrations
from django.db.models import Count

# Cap the per-group audit output so a very large merge does not flood the log.
MAX_AUDIT_LINES = 200


def _keep_and_dups(model, **group):
    """Return (keep, [dup, ...]) for one duplicate group, oldest row kept."""
    objs = list(model.objects.filter(**group).order_by("created_at", "id"))
    if not objs:
        return None, []
    return objs[0], objs[1:]


def _merge_duplicates(apps):
    Study = apps.get_model("dicom_handler", "DICOMStudy")
    Series = apps.get_model("dicom_handler", "DICOMSeries")
    Instance = apps.get_model("dicom_handler", "DICOMInstance")
    FileExport = apps.get_model("dicom_handler", "DICOMFileExport")
    RTImport = apps.get_model("dicom_handler", "RTStructureFileImport")

    removed = {"study": 0, "series": 0, "instance": 0}
    audits = []

    def audit(msg):
        if len(audits) < MAX_AUDIT_LINES:
            audits.append(msg)

    # 1) Studies: unique by (patient, study_instance_uid)
    study_groups = list(
        Study.objects.values("patient", "study_instance_uid")
        .annotate(n=Count("id"))
        .filter(n__gt=1)
    )
    for g in study_groups:
        keep, dups = _keep_and_dups(
            Study, patient=g["patient"], study_instance_uid=g["study_instance_uid"]
        )
        for dup in dups:
            Series.objects.filter(study=dup).update(study=keep)
        if dups:
            Study.objects.filter(id__in=[d.id for d in dups]).delete()
            removed["study"] += len(dups)
